const labels = [
  '01_Revenue_2026',
  '02_Infrastructure_2026',
  '03_SaaS_Tech_2026',
  '04_Marketing_2026',
  '05_Operations_2026',
  '06_Governance_2026'
];

const filters = [
  {
    label: '01_Revenue_2026',
    criteria: { query: 'from:(gumroad.com OR fieldnation.com OR paypal.com) (payout OR \"sent you money\" OR \"payment received\")' }
  },
  {
    label: '02_Infrastructure_2026',
    criteria: { query: 'from:(amazon.com OR cloudflare.com OR xfinity.com OR godaddy.com) (VPC OR \"AWS Billing\" OR \"monthly statement\")' }
  },
  {
    label: '03_SaaS_Tech_2026',
    criteria: { query: 'from:(anthropic.com OR notion.so OR openai.com OR google.com) subject:(receipt OR invoice OR \"your order\")' }
  },
  {
    label: '04_Marketing_2026',
    criteria: { query: 'from:(facebook.com OR ads.google.com OR canva.com OR fiverr.com OR mailchimp.com) (receipt OR invoice OR campaign OR \"ad spend\")' }
  },
  {
    label: '05_Operations_2026',
    criteria: { query: 'from:(aliexpress.com OR newegg.com OR bhphotovideo.com OR ups.com OR usps.com) (order OR shipment OR invoice OR receipt)' }
  },
  {
    label: '06_Governance_2026',
    criteria: { query: 'from:(sos.ga.gov OR sam.gov OR irs.gov) OR subject:(\"tax filing\" OR \"annual report\" OR \"registered agent\" OR \"bank alert\")' }
  }
];

return [{ json: { labels, filters } }];

const input = $input.first().json;
const labels = input.labels;
const filters = input.filters;
const results = { created_labels: [], created_filters: [], errors: [] };

// Create labels
for (const labelName of labels) {
  try {
    const resp = await this.helpers.httpRequestWithAuthentication.call(this, 'gmailOAuth2', {
      method: 'POST',
      url: 'https://gmail.googleapis.com/gmail/v1/users/me/labels',
      body: {
        name: labelName,
        labelListVisibility: 'labelShow',
        messageListVisibility: 'show'
      },
      json: true
    });
    results.created_labels.push({ name: labelName, id: resp.id });
  } catch (e) {
    if (e.message && e.message.includes('already exists')) {
      // Get existing label ID
      const listResp = await this.helpers.httpRequestWithAuthentication.call(this, 'gmailOAuth2', {
        method: 'GET',
        url: 'https://gmail.googleapis.com/gmail/v1/users/me/labels',
        json: true
      });
      const existing = listResp.labels.find(l => l.name === labelName);
      if (existing) results.created_labels.push({ name: labelName, id: existing.id, note: 'already existed' });
    } else {
      results.errors.push({ label: labelName, error: e.message });
    }
  }
}

// Create filters
for (const f of filters) {
  const labelEntry = results.created_labels.find(l => l.name === f.label);
  if (!labelEntry) {
    results.errors.push({ filter: f.label, error: 'label not found' });
    continue;
  }
  try {
    const resp = await this.helpers.httpRequestWithAuthentication.call(this, 'gmailOAuth2', {
      method: 'POST',
      url: 'https://gmail.googleapis.com/gmail/v1/users/me/settings/filters',
      body: {
        criteria: f.criteria,
        action: {
          addLabelIds: [labelEntry.id]
        }
      },
      json: true
    });
    results.created_filters.push({ label: f.label, filterId: resp.id });
  } catch (e) {
    results.errors.push({ filter: f.label, error: e.message });
  }
}

return [{ json: results }];
